#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, M, L, R;
    cin >> N >> M >> L >> R;

    long long total = R - L + 1;
    long long evenCount = total / 2 + ((total % 2 == 0 && L % 2 == 0) ? 1 : 0);
    long long oddCount = total - evenCount;

    const long long mod = 998244353;

    auto modInverse = [&](long long x) {
        return computePower(x, mod - 2);
    };

    auto computePower = [&](long long base, long long exp) {
        long long res = 1;
        long long b = base % mod;
        long long e = exp;
        while (e > 0) {
            if (e & 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            e >>= 1;
        }
        return res;
    };

    long long result;
    long long totalCells = N * M;
    if (totalCells % 2 == 1) {
        result = computePower(evenCount + oddCount, totalCells);
    } else {
        long long sum = (computePower(evenCount + oddCount, totalCells) + computePower(evenCount - oddCount, totalCells)) % mod;
        result = (sum * modInverse(2)) % mod;
    }

    cout << result << "\n";

    return 0;
}
